const result = await Aboutme.plugins.openai.sendMessage({agentId: 'assistant-1', message: '你好'});
if (result.success) {
  setResult(result.response);
} else {
  setResult(`错误: ${result.error}`);
}

const context = JSON.stringify([{role: 'user', content: '我叫张三'}, {role: 'assistant', content: '你好，张三！'}]);
const result = await Aboutme.plugins.openai.sendMessage({agentId: 'assistant-1', message: '我叫什么名字？', contextJson: context});
setResult(result.response);

let allProviders = [];
let offset = 0;
const count = 10;

while (true) {
  const result = await Aboutme.plugins.openai.getProviders({offset, count});
  allProviders = allProviders.concat(result.data);

  if (!result.hasMore) break;
  offset += count;
}

setResult(`共加载 ${allProviders.length} 个服务商`);

const result = await Aboutme.plugins.openai.testProvider({providerId: 'ollama'});
if (result.success) {
  setResult(`${result.provider} 连接成功`);
} else {
  setResult(`连接失败: ${result.error}`);
}
